insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, anio_registro, cota_msnm, este, norte, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalezas_ambiental, fortalezas_social, fortalezas_economico, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('6f61dbc3-de3a-48ec-883e-4ce3cb707c6e', 'LA NIEBLA', generar_slug_unico('LA NIEBLA', '6f61dbc3-de3a-48ec-883e-4ce3cb707c6e'), (select id from categorias_oficiales where slug = 'bioproductos-servicios-sostenibles'), 'Bucaramanga', (select id from veredas where municipio = 'Bucaramanga' and slug = 'san-jose'), 'ALTO DE LOS PADRES VEREDA SAN JOSE- CORREGIMIENTO 3 FINCA LA NIEBLA', 7.12418, -73.07998, 'El restaurante la Niebla se enfoca en dar a concocer la gastronomía local a través de sus platos fuertes carnes, pescados y dentro de sus instalaciones hay…', 'El restaurante la Niebla se enfoca en dar a concocer la gastronomía local a través de sus platos fuertes carnes, pescados y dentro de sus instalaciones hay un sendero llamado Bosque de Niebla el cual permite  que el visitante se pueda conectar con el medio natural llevandose una experiencia de bienestar y salud. En cuanto al tema gastronomico se están implementando huertas ecologicas de hortalizas , cafe organico entre otros para consumo del mismo restaurante. La población objetivo son familias, empresas e instituciones educativas.', 'GASTRONÓMICO', '3103248309 - 3124090107', '3103248309 - 3124090107', 'jmgpuyana@hotmail.com', 'JUAN MANUEL GONZALEZ PUYANA', '5563651-9', 'Natural', null, 'Cámara de comercio y RUT', 'DIEGO GUTIERREZ', 'RETIRADO', 'Satisfactorio', 2022, '1.645 msnm', '73.07998', '7.12418', 'No actualizó', 'No se realizo visita ni se aplico ficha de verificacion', 'No', null, null, null, 'Requiere', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'No', 'B2B', null, null, 'Contribuye a la biodiversidad conservando flora y fauna local en el bosque de niebla. Regulación hídrica. Mantiene la calidad y eficiencia del agua gracias a la regulación hídrica del bosque. Reduce gases de efecto invernadero con gran cantidad de árboles. Disminuye emisiones y mejora la salud con alimentos naturales de huerta propia. Sensibiliza sobre agroindustria sostenible y agroturismo.', 'Espacios agradables: Entorno natural que facilita un ambiente relajado para tareas diarias. Actividades lúdicas y alimentación fomentan un ambiente laboral de calidad. Promueve la economía local generando empleo para la comunidad campesina. Pagos justos y a tiempo optimizan el trabajo y satisfacción laboral.', 'Decisiones rápidas en precios y promociones mejoran la eficiencia operativa. Costos operativos bajos aumentan larentabilidad  del restaurante.', true, false, false, false, false);
