insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, anio_registro, cota_msnm, este, norte, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalezas_ambiental, fortalezas_social, fortalezas_economico, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('1fd335fa-14cc-4219-9b0a-200c462f056b', 'VIVERO EL DÍA TERCERO', generar_slug_unico('VIVERO EL DÍA TERCERO', '1fd335fa-14cc-4219-9b0a-200c462f056b'), (select id from categorias_oficiales where slug = 'calidad-ambiental'), 'Girón', (select id from veredas where municipio = 'Girón' and slug = 'perimetro-urbano'), 'CALLE 47 # 26-85 POBLADO', 7.075555555555555, -73.17, 'Empresa dedicada a la investigacion y el  tratamiento de semillas de especies nativas, con el fin de propagar y conservar las especies nativas de colombia,…', 'Empresa dedicada a la investigacion y el  tratamiento de semillas de especies nativas, con el fin de propagar y conservar las especies nativas de colombia, con el fin de preservar principalmente aquellas especies en estado de vulnerabilidad', 'SEMILLAS Y PLANTAS', '3152244441', '573152244441', 'viveroeldiatercero@gmail.com', 'LUIS EDURADO PINZON QUIÑONEZ', '1098618790-1', 'Natural', null, 'Cámara de comercio', 'ANDRES VALDERRAMA', 'ACTIVO', 'Dinamizadoras', 2023, '689,1 msnm', '73°10''12''''', '7°4''32''''', 'Actualizó', 'Se realizo visita y se actualizo ficha de verificacion', null, null, 'Acueducto', null, null, null, 'No', 'No', null, 'Sí', 'No', null, null, null, null, null, null, null, null, null, 'No', 'B2C', 'No', 'NO', 'Investigación permanente en reproducción de nuevas especies. Reproducción de especies nativas. Actividades sostenibles', 'Siembra regular de plantas en zonas verdes del municipio de Girón. Colines de plantas dispuestas para planes de reforestación', 'Modelo de negocio rentable. Empresa legalmente registrada en Cámara de Comercio', true, false, false, false, true);
